#!/usr/bin/env python3
"""Batch fix all autogenerated wrapper docstrings across API modules."""

import re
from pathlib import Path
from typing import Any

def snake_to_words(name: str) -> str:
    """Convert snake_case to space-separated words."""
    return name.replace("_", " ")

def generate_docstring(func_name: str, api_path: str, params: list[str]) -> str:
    """Generate comprehensive Google-style docstring."""
    operation = snake_to_words(func_name).title()
    
    # Build Args section
    args_section = ""
    for param in params:
        if "**" in param:
            args_section += "\n        **kwargs: Additional request parameters (timeout, retry, headers, dry_run, etc.)."
        elif ":" in param:
            param_name = param.split(":")[0].strip()
            if param_name not in ["self"]:
                args_section += f"\n        {param_name}: {snake_to_words(param_name)}."
    
    docstring = f'''"""{ operation}.
    
    Send a request to { api_path}. Returns processed result from
    ``process_result(...)`` and accepts ``RequestParameters`` overrides.
    
    Args:{args_section}
    
    Returns:
        Any: The processed response containing the requested data.
    
    Raises:
        BritecoreError: Various exceptions from process_result if the API returns an error.
    """'''
    
    return docstring

def fix_module(file_path: Path) -> int:
    """Fix all autogenerated docstrings in a module. Returns count of fixes."""
    content = file_path.read_text(encoding="utf-8")
    original = content
    fixes = 0
    
    # Find all functions with "Autogenerated wrapper" docstrings
    pattern = r'def (\w+)\((.*?)\) -> Any:\s+"""Autogenerated wrapper for ``([^`]+)``\."""'
    
    def replacer(match: re.Match) -> str:
        nonlocal fixes
        func_name = match.group(1)
        params_str = match.group(2)
        api_path = match.group(3)
        
        # Parse parameters
        params = [p.strip() for p in params_str.split(",") if p.strip()]
        
        # Generate new docstring
        new_docstring = generate_docstring(func_name, api_path, params)
        
        # Return the function definition with new docstring
        fixes += 1
        return f'def {func_name}({params_str}) -> Any:\n    {new_docstring}'
    
    # Apply replacements
    content = re.sub(pattern, replacer, content, flags=re.DOTALL)
    
    if fixes > 0:
        file_path.write_text(content, encoding="utf-8")
        print(f"✓ {file_path.name}: {fixes} docstrings fixed")
    
    return fixes

# Main execution
if __name__ == "__main__":
    api_calls_root = Path("src/britecore_sdk/api/api_calls")
    total_fixes = 0
    
    # Fix v2 modules with autogenerated wrappers
    for version_dir in [api_calls_root / "v2", api_calls_root / "v1"]:
        if not version_dir.exists():
            continue
        
        for module_file in sorted(version_dir.glob("*.py")):
            if module_file.name in ["__init__.py", "async_calls.py"]:
                continue
            
            module_fixes = fix_module(module_file)
            total_fixes += module_fixes
    
    print(f"\n✓ Total: {total_fixes} docstrings fixed")

